INSERT INTO `court_verdicts` VALUES (1,1,'Judicial Trial','Pengajuan Kasus & Berkas BAP (Case Filing)','Penyidik LSPD menyusun berkas perkara BAP lengkap beserta barang bukti foto/video Body Cam dan menyerahkannya ke Pengadilan / Kejaksaan.','Foto Barang Bukti, Rekaman Body Cam, Dokumen BAP, Daftar Saksi','2026-10-07 07:58:14','2026-10-07 07:58:14'),(2,2,'Judicial Trial','Sidang Perdana & Pembacaan Dakwaan (Arraignment)','Hakim membaca surat dakwaan di hadapan terdakwa dan pengacara penasihat hukum. Terdakwa menyatakan pembelaan (Guilty / Not Guilty).','Surat Dakwaan Jaksa Penuntut Umum','2026-10-07 07:58:14','2026-10-07 07:58:14'),(3,3,'Judicial Trial','Pembuktian & Pemeriksaan Saksi (Evidentiary Hearing)','Pemeriksaan saksi-saksi ahli, penyidik polisi, dan pengujian keabsahan barang bukti di persidangan.','Keterangan Saksi Officer, Hasil Uji GSR/Narkoba, Bukti Fisik','2026-10-07 07:58:14','2026-10-07 07:58:14'),(4,4,'Judicial Trial','Vonis Hakim & Eksekusi Hukuman (Court Verdict)','Hakim menjatuhkan vonis resmi hukuman penjara khusus, denda kompensasi, atau pencabutan lisensi permanen. Putusan hakim bersifat mengikat dan final.','Salinan Putusan Resmi Pengadilan','2026-10-07 07:58:14','2026-10-07 07:58:14');
/*!40000 ALTER TABLE `court_verdicts` ENABLE KEYS */;
UNLOCK TABLES;

