INSERT INTO `incident_commands` VALUES (1,'Incident Commander (IC)','Sergeant / Command Staff','Memegang komando tertinggi di TKP, mengelola saluran radio TAC, memberikan otorisasi PIT/Spike/Breach, bernegosiasi atau menunjuk Negosiator, serta menjamin keutuhan barang bukti.','Perintah verbal IC wajib dipatuhi seluruh unit responder.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(2,'Primary Unit (Pursuit Leader)','Officer I & Above','Unit terdepan dalam iring-iringan pengejaran (10-57). Mempertahankan kontak visual 100% pada ekor target dan dilarang keras melakukan callout radio demi konsentrasi berkendara.','Jika mengalami rintangan/kecelakaan, langsung menyerahkan posisi Primary ke Secondary Unit.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(3,'Secondary Unit (Radio Navigator)','Officer I & Above','Unit kedua dalam pursuit line up. Bertanggung jawab penuh menyuarakan arah jalan, persimpangan, kecepatan, dan dinamika tersangka di radio dispatch.','Navigasi jalan yang akurat memungkinkan unit perimeter memotong lajur target.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(4,'Spike & Containment Unit','Officer II & Above','Menyiapkan barikade jalan, memasang Spike Strip dari blind spot tersangka, serta memblok rute pelarian (Box Car).','Pemasangan spike wajib dikoordinasikan terlebih dahulu ke radio.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(5,'Specialized Division - SWAT / METRO','SWAT Qualified Officers','Penanganan situasi penyanderaan (31-B), penggerebekan kartel, dan kejahatan bersenjata berat (10-71 Active Shootout).','Divisi taktis penerobos utama di area bahaya tinggi.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(6,'Specialized Division - Air Support (ASD)','Air Support Certified Pilot','Unit helikopter untuk pemantauan udara, memberikan visual pelarian suspect dari langit, serta melacak jejak pelarian di area pegunungan/hutan.','Maksimal 1-2 helikopter sesuai Robbery Matrix.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(7,'Specialized Division - High-Speed Intercept (HSIU)','HSI Certified Drivers','Unit kendaraan performa tinggi (Corvette/Buffalo STX) khusus pursuit kecepatan tinggi di jalan tol dan area terbuka.','Memimpin pursuit di jalur lurus dan medan jalan tol.','2026-10-07 07:58:14','2026-10-07 07:58:14');
/*!40000 ALTER TABLE `incident_commands` ENABLE KEYS */;
UNLOCK TABLES;

