INSERT INTO `legal_procedures` VALUES (1,1,'Penangkapan & Borgol (Arrest)','Lakukan penangkapan terhadap tersangka secara terukur. Borgol kedua tangan tersangka di belakang punggung (10-95).','2026-10-07 07:58:14','2026-10-07 07:58:14'),(2,2,'Pembacaan Hak Miranda (Miranda Rights)','Wajib membacakan Hak Miranda sesaat setelah tersangka diborgol: \"Kamu berhak untuk diam, apapun yang kamu katakan dapat digunakan untuk melawan anda dan dibawa ke pengadilan. Anda berhak untuk menunjuk pengacara. jika tidak ada maka kami akan menentukan seorang pengacara untuk anda.\"','2026-10-07 07:58:14','2026-10-07 07:58:14'),(3,3,'Penggeledahan Badan & Kendaraan (Frisk & Search)','Lakukan penggeledahan fisik badan (Frisk) dan bagasi kendaraan. Amankan seluruh barang bukti ilegal (Take Evidence) seperti senjata tanpa izin, narkotika, atau barang curian.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(4,4,'Transportasi & Interogasi (Transport & BAP)','Bawa tersangka ke ruang interogasi Stasiun Alta / MRPD. Lakukan pemeriksaan singkat (BAP), foto mugshot, dan konfirmasi barang bukti.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(5,5,'Pencatatan MDT & Penahanan (MDT Booking & Jail)','Input seluruh data pelanggaran dan akumulasi denda & hukuman penjara ke dalam sistem MDT. Eksekusi penahanan tersangka di sel penjara (Cell/Jail).','2026-10-07 07:58:14','2026-10-07 07:58:14');
/*!40000 ALTER TABLE `legal_procedures` ENABLE KEYS */;
UNLOCK TABLES;

