INSERT INTO `penal_codes` VALUES (1,'STATE OFFENSES (PASAL 0)','(0)01','TREASON (COURT VERDICT/DEATH SENTENCE)',0,0,NULL,'Court Verdict','Pengkhianatan terhadap negara/pemerintah San Andreas, perang melawan negara, atau membantu musuh. Dihukum lewat Court Verdict atau Hukuman Mati.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(2,'STATE OFFENSES (PASAL 0)','(0)02','SEDITION (COURT VERDICT/DEATH SENTENCE)',0,0,NULL,'Court Verdict','Penghasutan atau menghimpun gerakan untuk menggulingkan atau merusak kekuasaan sah negara.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(3,'STATE OFFENSES (PASAL 0)','(0)03','REBELLION AND INSURRECTION (COURT VERDICT/DEATH SENTENCE)',0,0,NULL,'Court Verdict','Pemberontakan bersenjata atau perlawanan terorganisir melawan pemerintah sah.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(4,'STATE OFFENSES (PASAL 0)','(0)04','SABOTAGE OF STATE FUNCTIONS (COURT VERDICT/DEATH SENTENCE)',0,0,NULL,'Court Verdict','Sabotase fasilitas, infrastruktur kritis, atau jaringan komunikasi resmi milik negara.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(5,'STATE OFFENSES (PASAL 0)','(0)05','UNLAWFUL IMPERSONATION OF STATE AUTHORITY (COURT VERDICT/DEATH SENTENCE)',0,0,NULL,'Court Verdict','Penyamaran sebagai otoritas resmi negara/penegak hukum untuk tujuan kejahatan skala nasional.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(6,'STATE OFFENSES (PASAL 0)','(0)06','ESPIONAGE (COURT VERDICT/DEATH SENTENCE)',0,0,NULL,'Court Verdict','Spionase atau pembocoran dokumen dan rahasia pertahanan negara kepada musuh/organisasi ilegal.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(7,'STATE OFFENSES (PASAL 0)','(0)07','TERRORISM (COURT VERDICT/DEATH SENTENCE)',0,0,NULL,'Court Verdict','Tindak terorisme yang mengancam keselamatan nyawa publik, fasilitas vital, atau stabilitas negara.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(8,'STATE OFFENSES (PASAL 0)','(0)08','DOMESTIC TERRORISM (COURT VERDICT/DEATH SENTENCE)',0,0,NULL,'Court Verdict','Terorisme domestik/lokal yang menargetkan populasi sipil dan institusi pemerintah.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(9,'STATE OFFENSES (PASAL 0)','(0)09','COMPLICITY OF STATE ENEMIES',350000,90,NULL,'Felony','Memberi bantuan logistik, perlindungan, tempat tinggal, atau intelijen kepada musuh negara.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(10,'AGAINST PERSON (PASAL 1)','(1)01','CRIMINAL THREATS',6000,15,NULL,'Felony','Setiap orang yang secara sengaja mengancam akan melakukan tindak kejahatan kekerasan dengan maksud menimbulkan rasa takut yang wajar atas keselamatan orang lain.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(11,'AGAINST PERSON (PASAL 1)','(1)02','ASSAULT',6500,12,NULL,'Felony','Setiap orang yang secara melawan hukum mengancam atau mencoba menggunakan kekuatan fisik terhadap orang lain tanpa sentuhan fisik langsung.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(12,'AGAINST PERSON (PASAL 1)','(1)03','ASSAULT ON A GOVERNMENT EMPLOYEE',35000,30,NULL,'Felony','Setiap orang yang melakukan pengancaman atau penyerangan terhadap pegawai/petugas pemerintah yang sedang bertugas.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(13,'AGAINST PERSON (PASAL 1)','(1)04','ASSAULT WITH DEADLY WEAPON',28000,22,NULL,'Felony','Penyerangan menggunakan senjata api, pisau, atau senjata berbahaya lain yang berpotensi menyebabkan luka fisik parah atau kematian.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(14,'AGAINST PERSON (PASAL 1)','(1)05','ASSAULT WITH DEADLY WEAPON ON A GOVERNMENT EMPLOYEE',43500,35,NULL,'Felony','Penyerangan menggunakan senjata mematikan terhadap pegawai atau petugas pemerintah yang sedang bertugas.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(15,'AGAINST PERSON (PASAL 1)','(1)06','DOMESTIC VIOLENCE',32000,50,NULL,'Felony','Tindak kekerasan fisik atau penganiayaan terhadap pasangan, anggota keluarga, atau rekan se-rumah.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(16,'AGAINST PERSON (PASAL 1)','(1)07','BATTERY',35000,16,NULL,'Felony','Kontak fisik secara sengaja dan melawan hukum yang bersifat ofensif atau menyebabkan cedera ringan pada orang lain.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(17,'AGAINST PERSON (PASAL 1)','(1)08','BATTERY ON A GOVERNMENT EMPLOYEE',65000,20,NULL,'Felony','Kontak fisik secara sengaja dan melawan hukum terhadap pegawai/petugas pemerintah yang sedang bertugas.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(18,'AGAINST PERSON (PASAL 1)','(1)09','AGGRAVATED BATTERY',50000,35,NULL,'Felony','Penganiayaan berat yang mengakibatkan cedera fisik serius, luka permanen, atau melibatkan penggunaan senjata mematikan.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(19,'AGAINST PERSON (PASAL 1)','(1)10','GANG RELATED SHOOTING',30000,30,NULL,'Felony','Penembakan senjata api terhadap orang lain, kendaraan berpenumpang, atau tempat tinggal terkait aktivitas geng.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(20,'AGAINST PERSON (PASAL 1)','(1)11','ATTEMPTED SECOND DEGREE MURDER',59000,45,NULL,'Felony','Percobaan pembunuhan tanpa perencanaan terlebih dahulu, tetapi dilakukan dengan niat sengaja dan niat jahat.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(21,'AGAINST PERSON (PASAL 1)','(1)12','ATTEMPTED FIRST DEGREE MURDER',85000,60,NULL,'Felony','Percobaan pembunuhan berencana dengan niat sengaja terhadap orang lain.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(22,'AGAINST PERSON (PASAL 1)','(1)13','ATTEMPTED MURDER OF GOVERNMENT EMPLOYEE',160000,80,NULL,'Felony','Percobaan pembunuhan terhadap pegawai atau petugas pemerintah yang sedang melaksanakan tugas hukum yang sah.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(23,'AGAINST PERSON (PASAL 1)','(1)14','THIRD DEGREE MURDER',180000,150,NULL,'Felony','Pembunuhan yang disebabkan oleh kelalaian atau pengabaian ekstrem terhadap keselamatan nyawa manusia.','2026-10-07 07:58:13','2026-10-07 07:58:13'),(24,'AGAINST PERSON (PASAL 1)','(1)15','SECOND DEGREE MURDER',200000,470,NULL,'Felony','Pembunuhan tanpa perencanaan terlebih dahulu, tetapi dilakukan secara