INSERT INTO `promotion_qualifications` VALUES (1,'Cadet / Rookie','Officer I (PO I)','Administrative & Exam','1. Minimal masa kerja 7 hari aktif patroli.\n2. Lulus Ujian SOP Dasar & Penal Code.\n3. Bebas dari sanksi disiplin (0 Strike).\n4. Rekomendasi dari Field Training Officer (FTO).','2026-10-07 07:58:14','2026-10-07 07:58:14'),(2,'Officer I (PO I)','Officer II (PO II)','Performance','1. Minimal masa kerja 14 hari di rank PO I.\n2. Memiliki jam patroli aktif yang konsisten.\n3. Menguasai Prosedur 10-55 Traffic Stop & 10-38 Felony Stop.\n4. Lolos evaluasi kinerja dari Sergeant.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(3,'Officer II (PO II)','Officer III (PO III / Senior Officer)','Specialization','1. Minimal masa kerja 21 hari di rank PO II.\n2. Memiliki sertifikasi divisi khusus (SWAT / ASD / HSIU / K-9).\n3. Mampu menjadi Lead Officer saat patroli unit ADAM.\n4. Evaluasi dari Lieutenant.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(4,'Officer III (PO III)','Sergeant I (SGT I)','Leadership Examination','1. Minimal masa kerja 30 hari di kepolisian.\n2. Lulus Ujian Kepemimpinan & Incident Command (IC).\n3. Rekomendasi resmi dari Captain / Executive Staff.\n4. Memiliki kemampuan manajemen konflik & pembimbingan Rookie.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(5,'Sergeant I / II','Lieutenant & Command Staff','Executive Appointment','1. Penunjukan langsung dari Chief of Police / High Command.\n2. Rekam jejak kepemimpinan divisonal yang unggul.\n3. Bertanggung jawab atas pengelolaan operasional stasiun patroli.','2026-10-07 07:58:14','2026-10-07 07:58:14');
/*!40000 ALTER TABLE `promotion_qualifications` ENABLE KEYS */;
UNLOCK TABLES;

