INSERT INTO `rules` VALUES (1,'Aturan Umum','Ketentuan Dasar Robbery','1. Minimal suspect harus memiliki 1 sandera. Jika tidak ada sandera, polisi berhak melakukan breach-in. 2. Maksimal waktu HIT ROBBERY adalah 1 jam sebelum badai. 3. Dilarang melakukan aktivitas kriminal 30 menit sebelum badai.','Critical','2026-10-07 07:58:14','2026-10-07 07:58:14'),(2,'Robbery Matrix','Boosting Car / ATM Robbery Matrix','Pursuit: 6 min police, Barricade: 4 min police, Max Criminal: 2, Min Police: 6, Weapon Class: Class 1 + All Revolver, Vehicle: Based on Negotiation, Helicopter: Not Allowed.','Standard','2026-10-07 07:58:14','2026-10-07 07:58:14'),(3,'Robbery Matrix','LTD Store Robbery Matrix','Pursuit: 12 min police, Barricade: 8 min police, Max Criminal: 4, Min Police: 8, Weapon Class: Class 1, Vehicle: Based on Negotiation, Helicopter: Not Allowed.','Standard','2026-10-07 07:58:14','2026-10-07 07:58:14'),(4,'Robbery Matrix','Laundromat / Cash Exchange / Container Matrix','Pursuit: 12 min police, Barricade: 10 min police, Max Criminal: 6, Min Police: 10, Weapon Class: Class 2, Vehicle: Based on Negotiation, Helicopter: Not Allowed.','Standard','2026-10-07 07:58:14','2026-10-07 07:58:14'),(5,'Robbery Matrix','Jewel Store Robbery Matrix','Pursuit: 24 min police, Barricade: 10 min police, Max Criminal: 6, Min Police: 10, Weapon Class: Class 2, Vehicle: Based on Negotiation, Helicopter: Not Allowed.','Standard','2026-10-07 07:58:14','2026-10-07 07:58:14'),(6,'Robbery Matrix','Bobcat / Art Asylum Robbery Matrix','Pursuit: 30 min police, Barricade: 12 min police, Max Criminal: 8, Min Police: 12, Weapon Class: Class 2, Vehicle: Based on Negotiation, Helicopter: Not Allowed.','High','2026-10-07 07:58:14','2026-10-07 07:58:14'),(7,'Robbery Matrix','Fleeca Bank Robbery Matrix','Pursuit: 30 min police, Barricade: 12 min police, Max Criminal: 8, Min Police: 12, Weapon Class: Class 2, Vehicle: Based on Negotiation, Helicopter: 1 Police Helicopter.','High','2026-10-07 07:58:14','2026-10-07 07:58:14'),(8,'Robbery Matrix','Roxwood / Paleto Bank Robbery Matrix','Pursuit: 36 min police, Barricade: 14 min police, Max Criminal: 10, Min Police: 14, Weapon Class: Class 3, Vehicle: Based on Negotiation, Helicopter: 1 Police Helicopter.','High','2026-10-07 07:58:14','2026-10-07 07:58:14'),(9,'Robbery Matrix','Pacific Standard Bank Robbery Matrix','Pursuit: 40 min police, Barricade: 16 min police, Max Criminal: 12, Min Police: 16, Weapon Class: Class 3, Vehicle: Based on Negotiation, Helicopter: 2 Police Helicopters.','Critical','2026-10-07 07:58:14','2026-10-07 07:58:14'),(10,'Robbery Matrix','Maze Bank / Casino Heist Matrix','Pursuit: 46-50 min police, Barricade: 18-20 min police, Max Criminal: 14-16, Min Police: 18-20, Weapon Class: Class 3, Vehicle: Based on Negotiation, Helicopter: 2 Police Helicopters.','Critical','2026-10-07 07:58:14','2026-10-07 07:58:14'),(11,'Tactical Rules','Ketentuan Barricade & Special Escalation Rules','1. Jika officer lebih sedikit dari badside: Polisi berhak memakai senjata 1 level di atas badside + 1 helikopter. 2. Barricade di luar 5 blok: Polisi berhak ALL-IN officer (senjata tidak dinaikkan). 3. Setup One Way / Tangga Monyet: Polisi berhak ALL-IN officer + senjata 1 level di atas + 1 helikopter.','Critical','2026-10-07 07:58:14','2026-10-07 07:58:14');
/*!40000 ALTER TABLE `rules` ENABLE KEYS */;
UNLOCK TABLES;

