INSERT INTO `tactical_procedures` VALUES (1,'Traffic Stop','Prosedur Traffic Stop (10-55)','1) Hentikan Kendaraan (Nyalakan sirine/rotator, perintahkan matikan mesin).\n2) Lapor ke Central Dispatch (71-ADAMS/LINCOLN-503 10-55 at location).\n3) Dekati Kendaraan (Jalan di sisi kiri, tunjukkan badge & minta SIM/ID).\n4) Cek Identitas di MDT (Cek Warrant / BOLO).\n5) Konfirmasi Alasan Stop.\n6) Berikan Sanksi (Warning / Ticket).\n7) Akhiri Stop & Lepaskan Kendaraan.\n8) Laporan Selesai / Clear (Code 4).','Jika ada Warrant/BOLO -> Ubah ke Felony Stop (10-38) & panggil backup 10-78.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(2,'Felony Stop','Prosedur Felony Stop (10-38)','1) Lapor Dispatch & Request Backup 10-78.\n2) Perintahkan Matikan Mesin & Buang Kunci Out Window.\n3) Perintahkan Keluar Kendaraan Tangan Terangkat.\n4) Komando Keluar Unit (3... 2... 1... GO).\n5) Pointing Senjata dari Balik Cover.\n6) Posisi Suspect (Mata 1 & Mundur).\n7) Borgol & Pembacaan Hak Miranda.\n8) Pengecekan Kendaraan Suspect.\n9) Penanganan Impound.\n10) Laporan Clear / Code 4.','Kategori High Risk. Wajib bacakan Hak Miranda setelah diborgol.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(3,'Suspicious Activity','Prosedur 10-34 (Suspicious Activity & Narkoba)','1) Pemantauan Visual & Laporan Awal Radio Dispatch.\n2) Interogasi Lisan & Frisking Fisik Ringan.\n3) Penanganan Barang Bukti & Penahanan (10-95).\n4) Transisi Darurat (Pengejaran Active 10-57 jika melarikan diri).','Amankan barang bukti (Take Evidence) & bawa ke Alta / MRPD Station.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(4,'Silent Alarm','Prosedur 31-A (Silent Alarm & Respon Perampokan Awal)','1) Transmisi Respon Radio (31-A Call-out).\n2) Pendekatan Senyap (Silent Approach, sirine mati).\n3) Pembentukan Perimeter Awal (Containment).\n4) Penetapan Saluran TAC & Incident Commander (IC).','Silent approach agar tidak memicu kepanikan / membahayakan warga.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(5,'Active Robbery','Prosedur 31-B (Active Robbery & Hostage Situation)','1) Laporan Radio Respon Awal.\n2) Broadcast Laporan Situasi Aktif (Warna 60, Jumlah 61, Hostage).\n3) Negosiasi Taktis Sandera (Ada sandera -> Negosiasi; Tanpa sandera -> Breach-in).\n4) Transisi Pengejaran (Pursuit Mode).\n5) Clearance Broadcast (Code 4).','Penuhi tuntutan wajar (free passage / no spike) demi keselamatan sandera.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(6,'Active Shootout','Gang War / Active Shootout (10-71)','1) Laporkan 10-71 & tetapkan Code 3 respon darurat.\n2) Dilarang unit pertama langsung menerobos kill zone.\n3) Tunggu di perimeter luar & buat barikade jalan.\n4) Sterilisasi TKP, Uji GSR, Amankan Bukti Senjata & Evakuasi Medis ke Sector A.','Keselamatan Officer prioritas mutlak. Perform GSR Test & Take Evidence.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(7,'Perampokan','Prosedur Respon Robbery (Perampokan)','1) Persyaratan Unit Patroli (ADAM/ROBERT max 3 officer).\n2) First Responder 10-23 & Laporan Visual.\n3) Negosiasi (Sandera -> IC Negotiate; Tanpa Sandera -> Breach-in).\n4) Alokasi Saluran TAC.\n5) Pursuit Transition & Batasan Unit (1 mobil -> 4-5 unit; 2 mobil -> 8-10 unit).\n6) Prosedur VCB (Visual Contact Broken).','Batas unit pengejar disesuaikan ketat dengan jumlah kendaraan tersangka.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(8,'Pursuit','Prosedur Pursuit (Pengejaran)','1) Formasi Iring-iringan (2 Interceptor Henry/Golf depan, 3 Basic Adam/Lincoln belakang).\n2) Air Support / Motor Squad (AIR / MARY) atas izin IC.\n3) Primary Unit fokus 100% nyetir (dilarang callout); Secondary Unit navigator radio.\n4) Clean Pursuit vs Hot Pursuit (Toleransi 1x lompatan tak logis).\n5) Otorisasi PIT setelah 10+ menit atas verbal approval IC/Sergeant.','Max 4-5 unit aktif per kendaraan buronan.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(9,'PIT Maneuver','Prosedur P.I.T (Precision Immobilization Technique)','1) Penyelarasan Posisi (Sejajarkan bumper depan dengan quarter-panel belakang target).\n2) Kontak Fisik Terkendali.\n3) Akselerasi Konstan.\n4) Spin Out (Target putar 180 deg).\n5) Vehicle Pinning oleh Backup Unit.','Kecepatan ideal 40-55 MPH. Butuh verbal authorization dari IC / Sergeant.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(10,'Sita Kendaraan','Prosedur Impound Sita (Sita Kendaraan)','1) Kondisi: Kendaraan di TKP, masuk air, atau berganti kendaraan saat pursuit (butuh izin IC).\n2) Cek F1 Checking Vehicle & Dokumentasi Foto.\n3) Cek MDT & Bagasi/Glovebox.\n4) Amankan Barang Ilegal.\n5) Eksekusi F1 Impound Sita, Catat MDT & Forum Impound Police.','Jika suspect tertangkap, gunakan IMPOUND VEHICLE PUBLIC (bukan Impound Police).','2026-10-07 07:58:14','2026-10-07 07:58:14'),(11,'Release Vehicle','Prosedur Pengeluaran Kendaraan (Release Vehicle)','1) Verifikasi Identitas & Plate Number di MDT & Website Putih.\n2) Cek Notes Profil (kasus khusus / larangan keluar).\n3) Cek Status BOLO & Pelunasan Denda.\n4) Penyerahan & Biaya Regulasi ($5,000 denda resmi).','Dilarang mengeluarkan kendaraan berstatus BOLO / memiliki catatan khusus tanpa izin IC.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(12,'Integrasi Body Cam','Prosedur & Integrasi Body Cam (ShareX & FiveManage)','1) Wajib aktifkan Body Cam sejak 10-41 (On Duty) hingga 10-42 (Off Duty).\n2) Upload ke ShareX / FiveManage / Discord Evidence Channel.\n3) Sertakan URL link bukti video pada Laporan Incident MDT.','Format nama file: [Tanggal] - [Nama Officer] - [Case ID].','2026-10-07 07:58:14','2026-10-07 07:58:14');
/*!40000 ALTER TABLE `tactical_procedures` ENABLE KEYS */;
UNLOCK TABLES;

