INSERT INTO `weapon_classes` VALUES (1,'Police Class 1','Cadet / Rookie & Above','Combat Pistol, AP Pistol, PD 2011, Heavy Pistol, JR136 Timberstrike, Taser, Flashlight, Nightstick','Senjata dinas utama untuk patroli harian.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(2,'Police Class 2','Officer II & Above / Special Patrol','Combat PDW, Assault SMG, SMG MK2, Revolver MK2, MI9, Colt Revolver, Pump Shotgun MK2, Bullpup Shotgun, Combat V7X, Vector Sector','Hanya dikeluarkan saat respon Code 3, Robbery Class 2, atau High Risk Call.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(3,'Police Class 3','Sergeant & SWAT / Special Ops Qualified','Carbine Rifle MK2, Special Carbine MK2, Assault Rifle MK2, Bullpup Rifle MK2, CQB Universal Bullpup, Modern Universal Bullpup, SA Tactical Rifle, XEN7 Warden PD, RRC3 Achromic','Otorisasi Incident Commander / Senior Command Officer.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(4,'Criminal Class 1','Illicit Civilians','Pistol .50, Ceramic Pistol, X17 Modular, Machine Pistol, ST84 Skulln Sword, MX18 Classyblue','Senjata api genggam ringan kriminal.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(5,'Criminal Class 2','Gangsters & Robbers','Mini SMG, Micro SMG, SMG, Navy Revolver, KVR, Pump Shotgun, Revolver Black, Sawn Off Shotgun, SDR7, VTN33 Graveshift','Senjata otomatis dan shotgun kriminal.','2026-10-07 07:58:14','2026-10-07 07:58:14'),(6,'Criminal Class 3','Cartels & Heavy Syndicate','Double Action, Assault Rifle, Carbine Rifle, MB47, AGC, BK12, Dragon, Scarl Godzilla, AK47 Purplefunk, AKT, Foolv2 RED, M6A9 Diamond Soul, Scarl Rusty, M4 T Neon, Integrale','Senjata militer dan assault rifles kelas berat.','2026-10-07 07:58:14','2026-10-07 07:58:14');
